"""Regenerate docs/variable_map.md from the input declarations, so it cannot drift from the code.

Run from the repository root:  python tools/generate_variable_map.py
"""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from condenser_app.schemas import iter_inputs  # noqa: E402
from condenser_app.service import MODULES  # noqa: E402


def cell(text) -> str:
    return str(text or "").replace("|", "/")


def main() -> None:
    lines = [
        "# Variable map",
        "",
        "Generated by `tools/generate_variable_map.py`. Do not edit by hand.",
        "",
        "Field paths are this project's. The supplied data-entry sheets were not available, so their names still need mapping onto these. "
        "Internal units are SI, with temperature in degrees Celsius; the form uses the display unit.",
    ]
    for key, module in MODULES.items():
        lines += ["", f"## {module.title} (`{key}`)", "", "| Field | Meaning | Internal unit | Form unit | Required | Source |", "|---|---|---|---|---|---|"]
        for path, _, _, meta in iter_inputs(module.new_inputs()):
            required = "yes" if meta["required"] else ""
            lines.append(f"| `{path}` | {cell(meta['label'])} | {cell(meta['unit'])} | {cell(meta['display_unit'])} | {required} | {cell(meta['source'])} |")
    (ROOT / "docs" / "variable_map.md").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
